package kr.co.ipharmkorea.dongwonhub;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.webkit.*;import android.widget.*;import org.json.*;import java.io.*;import java.net.HttpURLConnection;import java.net.URL;import java.security.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
public final class MainActivity extends Activity {
private static final String HUB="https://talk.ipharmkorea.com";private static final int VERSION_CODE=10001,PICK=120,INSTALL=121;private WebView web;private TextView status;private ValueCallback<Uri[]> chooser;private final AtomicBoolean checking=new AtomicBoolean(false);private boolean pendingInstall=false;
public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(Color.rgb(235,243,244));getWindow().setNavigationBarColor(Color.WHITE);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.WHITE);setContentView(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);root.addView(bar,new LinearLayout.LayoutParams(-1,dp(48)));Button back=new Button(this);back.setText("‹");back.setContentDescription("뒤로 가기");bar.addView(back,new LinearLayout.LayoutParams(dp(44),-1));back.setOnClickListener(v->onBackPressed());status=new TextView(this);status.setText("동원HUB");status.setTextSize(17);bar.addView(status,new LinearLayout.LayoutParams(0,-2,1));Button reload=new Button(this);reload.setText("↻");reload.setContentDescription("새로고침");bar.addView(reload,new LinearLayout.LayoutParams(dp(44),-1));reload.setOnClickListener(v->web.loadUrl(HUB+"/?mobile=android&nativeVersion="+VERSION_CODE+"&_="+System.currentTimeMillis()));web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setCacheMode(WebSettings.LOAD_NO_CACHE);s.setSafeBrowsingEnabled(true);s.setUserAgentString(s.getUserAgentString()+" DongwonHUBAndroid/"+VERSION_CODE);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,true);
web.setWebChromeClient(new WebChromeClient(){public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> cb,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=cb;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(i,PICK);}catch(Exception e){chooser.onReceiveValue(null);chooser=null;}return true;}});
web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){Uri u=r.getUrl();if(r.isForMainFrame()&&"dongwonhub".equals(u.getScheme())&&"check-update".equals(u.getHost())){checkUpdate();return true;}if(!"https".equals(u.getScheme()))return true;if(!r.isForMainFrame())return false;if("talk.ipharmkorea.com".equals(u.getHost())&&(u.getPort()==-1||u.getPort()==443))return false;external(u);return true;}public void onPageFinished(WebView w,String url){status.setText("동원HUB");CookieManager.getInstance().flush();}public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())status.setText("연결 확인 후 ↻ 새로고침");}});
web.setDownloadListener((url,ua,disp,mime,length)->{if(!url.startsWith("https://")){Toast.makeText(this,"이 파일은 PC 웹에서 내려받아주세요.",Toast.LENGTH_LONG).show();return;}try{DownloadManager.Request request=new DownloadManager.Request(Uri.parse(url));request.addRequestHeader("User-Agent",ua);if(url.startsWith(HUB+"/")){String c=CookieManager.getInstance().getCookie(url);if(c!=null)request.addRequestHeader("Cookie",c);}String name=URLUtil.guessFileName(url,disp,mime).replaceAll("[^\\p{L}\\p{N}._ -]","_");request.setTitle(name);request.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);request.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,name);((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(request);}catch(Exception e){external(Uri.parse(url));}});web.loadUrl(HUB+"/?mobile=android&nativeVersion="+VERSION_CODE);checkUpdate();}
private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private void external(Uri u){try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){Toast.makeText(this,"링크를 열 앱이 없습니다.",Toast.LENGTH_SHORT).show();}}public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else moveTaskToBack(true);}protected void onPause(){super.onPause();CookieManager.getInstance().flush();}protected void onDestroy(){if(chooser!=null)chooser.onReceiveValue(null);if(web!=null)web.destroy();super.onDestroy();}
protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==PICK&&chooser!=null){ArrayList<Uri> uris=new ArrayList<>();if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null)for(int j=0;j<data.getClipData().getItemCount();j++)uris.add(data.getClipData().getItemAt(j).getUri());else if(data.getData()!=null)uris.add(data.getData());}chooser.onReceiveValue(uris.isEmpty()?null:uris.toArray(new Uri[0]));chooser=null;}if(req==INSTALL&&pendingInstall){pendingInstall=false;if(getPackageManager().canRequestPackageInstalls())installUpdate();}}
private HttpURLConnection connection(String url)throws Exception{if(!url.startsWith(HUB+"/"))throw new IOException("Untrusted host");HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(30000);c.setRequestProperty("Cache-Control","no-cache");if(c.getResponseCode()!=200)throw new IOException("Update HTTP "+c.getResponseCode());return c;}
private void checkUpdate(){if(!checking.compareAndSet(false,true))return;new Thread(()->{try{HttpURLConnection c=connection(HUB+"/api/app-updates");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>65536)throw new IOException();out.write(b,0,n);}}finally{c.disconnect();}JSONArray list=new JSONObject(new String(out.toByteArray(),"UTF-8")).getJSONArray("releases");for(int j=0;j<list.length();j++){JSONObject r=list.getJSONObject(j);if("android".equals(r.getString("platform"))&&r.getInt("versionCode")>VERSION_CODE){runOnUiThread(()->status.setText("업데이트 다운로드 중…"));downloadUpdate(r);break;}}}catch(Exception e){runOnUiThread(()->{status.setText("업데이트 확인 실패");Toast.makeText(this,"앱 업데이트를 완료하지 못했습니다. 네트워크와 배포 파일을 확인해주세요.",Toast.LENGTH_LONG).show();});}finally{checking.set(false);}},"hub-update").start();}
private String hash(File f)throws Exception{MessageDigest h=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[131072];int n;while((n=in.read(b))!=-1)h.update(b,0,n);}StringBuilder value=new StringBuilder();for(byte b:h.digest())value.append(String.format("%02x",b&255));return value.toString();}
private void downloadUpdate(JSONObject r)throws Exception{String relative=r.getString("downloadPath"),expected=r.getString("sha256");long size=r.getLong("size");int version=r.getInt("versionCode");if(!relative.matches("/api/app-download\\?platform=android&versionCode=\\d+")||!expected.matches("[a-f0-9]{64}")||size<1024||size>40L*1024*1024)throw new IOException("Invalid release");File f=new File(getCacheDir(),"hub-update.apk");if(!f.isFile()||f.length()!=size||!hash(f).equals(expected)){File temp=new File(getCacheDir(),"hub-update.partial");HttpURLConnection c=connection(HUB+relative);try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(temp)){byte[] b=new byte[131072];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>size)throw new IOException();out.write(b,0,n);}if(total!=size)throw new IOException();}finally{c.disconnect();}if(!hash(temp).equals(expected)){temp.delete();throw new IOException("Digest mismatch");}if(!temp.renameTo(f))throw new IOException("Save failed");}PackageManager pm=getPackageManager();PackageInfo archive=pm.getPackageArchiveInfo(f.getPath(),PackageManager.GET_SIGNATURES),current=pm.getPackageInfo(getPackageName(),PackageManager.GET_SIGNATURES);if(archive==null||!getPackageName().equals(archive.packageName)||archive.versionCode!=version||archive.signatures==null||current.signatures==null||!Arrays.equals(archive.signatures,current.signatures)){f.delete();throw new IOException("Signing identity mismatch");}runOnUiThread(()->{if(!isFinishing()){status.setText("새 버전 설치 확인");installUpdate();}});}
private void installUpdate(){if(!getPackageManager().canRequestPackageInstalls()){pendingInstall=true;new AlertDialog.Builder(this).setTitle("앱 업데이트 허용").setMessage("Android 설정에서 동원HUB의 앱 설치를 허용한 뒤 돌아오세요.").setPositiveButton("설정 열기",(d,w)->startActivityForResult(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())),INSTALL)).setNegativeButton("취소",(d,w)->pendingInstall=false).show();return;}Intent i=new Intent(Intent.ACTION_INSTALL_PACKAGE,Uri.parse("content://"+getPackageName()+".updates/update.apk"));i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(i);}catch(Exception e){Toast.makeText(this,"설치 화면을 열지 못했습니다.",Toast.LENGTH_LONG).show();}}
}
